// QAInviteCreateBulk is the builder for creating many QAInvite entities in bulk.
type QAInviteCreateBulk struct {
	config
	err      error
	builders []*QAInviteCreate
	conflict []sql.ConflictOption
}

// Save creates the QAInvite entities in the database.
func (qicb *QAInviteCreateBulk) Save(ctx context.Context) ([]*QAInvite, error) {
	if qicb.err != nil {
		return nil, qicb.err
	}
	specs := make([]*sqlgraph.CreateSpec, len(qicb.builders))
	nodes := make([]*QAInvite, len(qicb.builders))
	mutators := make([]Mutator, len(qicb.builders))
	for i := range qicb.builders {
		func(i int, root context.Context) {
			builder := qicb.builders[i]
			builder.defaults()
			var mut Mutator = MutateFunc(func(ctx context.Context, m Mutation) (Value, error) {
				mutation, ok := m.(*QAInviteMutation)
				if !ok {
					return nil, fmt.Errorf("unexpected mutation type %T", m)
				}
				if err := builder.check(); err != nil {
					return nil, err
				}
				builder.mutation = mutation
				var err error
				nodes[i], specs[i] = builder.createSpec()
				if i < len(mutators)-1 {
					_, err = mutators[i+1].Mutate(root, qicb.builders[i+1].mutation)
				} else {
					spec := &sqlgraph.BatchCreateSpec{Nodes: specs}
					spec.OnConflict = qicb.conflict
					// Invoke the actual operation on the latest mutation in the chain.
					if err = sqlgraph.BatchCreate(ctx, qicb.driver, spec); err != nil {
						if sqlgraph.IsConstraintError(err) {
							err = &ConstraintError{msg: err.Error(), wrap: err}
						}
					}
				}
				if err != nil {
					return nil, err
				}
				mutation.id = &nodes[i].ID
				mutation.done = true
				return nodes[i], nil
			})
			for i := len(builder.hooks) - 1; i >= 0; i-- {
				mut = builder.hooks[i](mut)
			}
			mutators[i] = mut
		}(i, ctx)
	}
	if len(mutators) > 0 {
		if _, err := mutators[0].Mutate(ctx, qicb.builders[0].mutation); err != nil {
			return nil, err
		}
	}
	return nodes, nil
}

